-- Oura — Сон
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'ouraring.com' OR LOWER(`name`) = LOWER('Oura'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Oura', NULL, 'https://ouraring.com', NULL, NULL, 'Смарт-кільце, що відстежує сон, відновлення, активність і стрес за 50+ показниками, з AI-помічником Oura Advisor, який пояснює ваші дані.', 'A smart ring that tracks sleep, readiness, activity and stress across 50+ health metrics, with the Oura Advisor AI companion that explains your data.', 'Oura Ring — розумне кільце, яке носять цілодобово. Воно відстежує понад 50 показників здоров''я — сон і його фази, пульс, серцево-судинні дані, активність і стрес — і щодня показує оцінки сну, готовності (Readiness) та активності. Oura Advisor, AI-помічник у застосунку, перетворює ці дані на персональні поради: чому ви погано спали, коли варто відпочити, як змінюється ваш стан. Саме кільце купується окремо; для повного доступу до щоденних інсайтів потрібне членство — $5,99 на місяць або $69,99 на рік (ціни можуть відрізнятися за регіоном), перший місяць безкоштовний. Без підписки кільце працює з обмеженими даними. Oura не є медичним виробом для діагностики.', 'Oura Ring is a smart ring worn day and night. It tracks more than 50 health metrics — sleep and sleep stages, heart rate, cardiovascular data, activity and stress — and shows daily Sleep, Readiness and Activity scores. Oura Advisor, the AI companion in the app, turns this data into personal guidance: why you slept badly, when to rest and how your condition is changing. The ring is bought separately; full access to daily insights requires a membership — $5.99 a month or $69.99 a year (prices may vary by region), with the first month free. Without a subscription the ring works with limited insights. Oura is not a diagnostic medical device.', 'Відстеження сну, пульсу, активності й стресу
Оцінки сну, готовності та активності
AI-помічник Oura Advisor
Носіння 24/7 у формі кільця', 'Tracks sleep, heart rate, activity and stress
Sleep, Readiness and Activity scores
Oura Advisor AI companion
Worn 24/7 as a ring', 'Люди, які хочуть краще спати й стежити за відновленням без годинника на руці.', 'People who want to sleep better and track recovery without wearing a watch.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
