INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Oura Ring is a smart ring worn day and night. It tracks more than 50 health metrics — sleep and sleep stages, heart rate, cardiovascular data, activity and stress — and shows daily Sleep, Readiness and Activity scores. Oura Advisor, the AI companion in the app, turns this data into personal guidance: why you slept badly, when to rest and how your condition is changing. The ring is bought separately; full access to daily insights requires a membership — $5.99 a month or $69.99 a year (prices may vary by region), with the first month free. Without a subscription the ring works with limited insights. Oura is not a diagnostic medical device.', 'manual' FROM DUAL WHERE @new = 1;
