-- Eight Sleep — Сон
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'eightsleep.com' OR LOWER(`name`) = LOWER('Eight Sleep'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Eight Sleep', NULL, 'https://www.eightsleep.com', NULL, NULL, 'Розумний чохол для матраца Pod: охолоджує й підігріває кожну половину ліжка окремо, відстежує сон біометричними датчиками й сам підлаштовує температуру вночі.', 'The Pod smart mattress cover: it cools and heats each side of the bed separately, tracks sleep with biometric sensors and adjusts the temperature automatically at night.', 'Eight Sleep Pod — система з чохла для матраца та блока Hub, що ставиться біля ліжка. Чохол з вбудованими біометричними датчиками охолоджує або підігріває кожну половину ліжка окремо в діапазоні приблизно від 13 до 43 °C, відстежує фази сну й показники здоров''я та протягом ночі сам змінює температуру, щоб подовжити глибокий сон і фазу REM. Налаштування й аналітика — у мобільному застосунку, є інтеграція з фітнес- і health-застосунками. Окремо можна додати основу з підйомом узголів''я, що допомагає при хропінні. Pod 6 коштує від $1 999.', 'Eight Sleep Pod is a system made of a mattress cover and a Hub unit placed beside the bed. The cover, with built-in biometric sensors, cools or heats each side of the bed separately within roughly 13–43 °C (55–110 °F), tracks sleep stages and health metrics and adjusts the temperature through the night to extend deep and REM sleep. Settings and analytics live in the mobile app, which integrates with fitness and health apps. An optional Base with head elevation helps with snoring. Pod 6 starts at $1,999.', 'Охолодження й підігрів кожної половини ліжка
Біометричні датчики в чохлі
Автоматичне підлаштування температури вночі
Основа з підйомом узголів''я (опція)', 'Cooling and heating for each side of the bed
Biometric sensors in the cover
Automatic overnight temperature adjustment
Optional Base with head elevation', 'Люди, яким заважає спати спека чи холод, і пари з різними вподобаннями щодо температури.', 'People whose sleep suffers from heat or cold, and couples with different temperature preferences.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
