INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Eight Sleep Pod is a system made of a mattress cover and a Hub unit placed beside the bed. The cover, with built-in biometric sensors, cools or heats each side of the bed separately within roughly 13–43 °C (55–110 °F), tracks sleep stages and health metrics and adjusts the temperature through the night to extend deep and REM sleep. Settings and analytics live in the mobile app, which integrates with fitness and health apps. An optional Base with head elevation helps with snoring. Pod 6 starts at $1,999.', 'manual' FROM DUAL WHERE @new = 1;
