-- Rise — Сон
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'risescience.com' OR LOWER(`name`) = LOWER('Rise'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Rise', NULL, 'https://www.risescience.com', NULL, NULL, 'Застосунок для сну й енергії: рахує ваш «борг сну» та циркадний ритм і щодня підказує, коли буде пік енергії, спад і час готуватися до сну.', 'A sleep and energy app: it calculates your sleep debt and circadian rhythm and tells you each day when to expect peak energy, dips and wind-down time.', 'Rise допомагає краще спати й мати більше енергії вдень, спираючись на два показники — борг сну та циркадний ритм. Уже в перший день застосунок аналізує історію даних телефона, визначає вашу потребу в сні й поточний борг, а з Apple Health, Oura чи Fitbit отримує точніші дані. Щодня він підказує, скільки триватиме ранкова млявість, коли буде пік концентрації та коли починати готуватися до сну, і нагадує про 16 науково обґрунтованих звичок у потрібний час. Застосунок увійшов до найкращих застосунків Apple 2026 року. Є безкоштовний пробний період; вартість підписки вказано в застосунку.', 'Rise helps you sleep better and have more energy during the day, based on two metrics — sleep debt and circadian rhythm. On day one the app analyses your phone''s data history to estimate your sleep need and current debt, and it gets more accurate data from Apple Health, Oura or Fitbit. Each day it tells you how long morning grogginess will last, when your focus will peak and when to start winding down, and reminds you of 16 science-based habits at the right time. It was named one of Apple''s Best Apps of 2026. There is a free trial; the subscription price is shown in the app.', 'Борг сну та циркадний ритм
Прогноз енергії на день
16 науково обґрунтованих звичок
Інтеграція з Apple Health, Oura, Fitbit', 'Sleep debt and circadian rhythm
Daily energy forecast
16 science-based habits
Apple Health, Oura and Fitbit integration', 'Люди з нестабільним режимом сну, студенти й ті, хто хоче більше енергії вдень.', 'People with irregular sleep, students and anyone who wants more energy during the day.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
