INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Sleep Cycle', NULL, 'https://www.sleepcycle.com', NULL, NULL, 'Трекер сну з розумним будильником, який будить у легкій фазі сну, аналізом нічних звуків і статистикою якості й тривалості сну.', 'A sleep tracker with a smart alarm that wakes you in a light sleep phase, night-time sound analysis and statistics on sleep quality and duration.', 'Sleep Cycle аналізує сон за допомогою мікрофона телефона чи годинника й будує статистику якості та тривалості сну. Розумний будильник спрацьовує в межах заданого вікна в момент легкого сну, тож прокидатися легше. Застосунок також розпізнає нічні звуки, зокрема хропіння й розмови уві сні, показує тенденції та допомагає виробити стабільний режим. Працює на iOS і Android. Базові функції безкоштовні; Premium відкриває розширену аналітику, є безкоштовний пробний період, а ціну підписки показано в застосунку.', 'Sleep Cycle analyses your sleep using your phone''s microphone or your watch and builds statistics on sleep quality and duration. The smart alarm goes off within a set window at a moment of light sleep, so waking up is easier. The app also recognises night-time sounds, including snoring and sleep talking, shows trends and helps you build a consistent routine. It works on iOS and Android. Basic features are free; Premium unlocks advanced analytics, with a free trial and the subscription price shown in the app.', 'Розумний будильник у фазі легкого сну
Статистика якості й тривалості сну
Розпізнавання хропіння й нічних звуків
iOS і Android', 'Smart alarm in a light sleep phase
