-- Cal AI — Харчування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'calai.app' OR LOWER(`name`) = LOWER('Cal AI'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Cal AI', NULL, 'https://www.calai.app', NULL, NULL, 'Підрахунок калорій за фото їжі: сфотографуйте страву, відскануйте штрихкод чи опишіть її — і застосунок порахує калорії, білки, жири й вуглеводи.', 'Calorie counting from food photos: snap your meal, scan a barcode or describe it and the app calculates calories, protein, fat and carbs.', 'Cal AI робить облік харчування майже автоматичним. Досить сфотографувати страву — AI розпізнає продукти, а на сумісних телефонах використовує датчик глибини, щоб оцінити об''єм порції, — і показує калорії та макронутрієнти. Можна також сканувати штрихкоди, описувати їжу словами, зберігати власні страви й рецепти та підтягувати тренування з фітнес-пристроїв. Застосунком користуються близько 5 млн людей. Працює на iOS і Android; є 3-денний безкоштовний пробний період, підписка оформлюється через App Store чи Google Play. Застосунок не замінює консультацію лікаря чи дієтолога.', 'Cal AI makes food tracking almost automatic. Just take a photo of your meal — AI recognises the foods and, on compatible phones, uses the depth sensor to estimate portion volume — and it shows calories and macronutrients. You can also scan barcodes, describe food in words, save your own meals and recipes and pull in workouts from fitness devices. About 5 million people use the app. It works on iOS and Android; there is a 3-day free trial, and subscriptions are handled through the App Store or Google Play. The app does not replace advice from a doctor or dietitian.', 'Калорії й макроси за фото страви
Оцінка об''єму порції датчиком глибини
Сканування штрихкодів і опис словами
Власні рецепти та синхронізація тренувань', 'Calories and macros from a meal photo
Portion volume estimate with depth sensor
Barcode scanning and text descriptions
Custom recipes and workout sync', 'Люди, які стежать за вагою чи харчуванням і не хочуть вручну шукати продукти в базі.', 'People watching their weight or diet who do not want to search food databases by hand.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
