-- SnapCalorie — Харчування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'snapcalorie.com' OR LOWER(`name`) = LOWER('SnapCalorie'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'SnapCalorie', NULL, 'https://www.snapcalorie.com', NULL, NULL, 'AI-облік харчування за фото чи голосом з персональними планами під кето, веганство, середземноморську та інші дієти; основні функції безкоштовні.', 'AI food logging from photos or voice with personal plans for keto, vegan, Mediterranean and other diets; core features are free.', 'SnapCalorie розпізнає їжу на фото за допомогою комп''ютерного зору й автоматично рахує поживну цінність, а страву можна також надиктувати голосом. За даними розробників, такий облік у 5 разів швидший за пошук у базі продуктів, а оцінка калорій удвічі точніша, ніж у дієтологів. Застосунок складає персональні плани харчування — кето, веганський, середземноморський, палео, вегетаріанський або без обмежень, — показує тенденції та має базу продуктів, рецепти й навчальні матеріали. Дані шифруються. Основні функції безкоштовні, без картки; є API для розробників. Працює на iOS і Android.', 'SnapCalorie recognises food in photos with computer vision and calculates nutrition automatically, and you can also dictate a meal by voice. According to the developers, logging this way is 5 times faster than searching a food database, and its calorie estimates are twice as accurate as nutritionists''. The app builds personal meal plans — keto, vegan, Mediterranean, paleo, vegetarian or unrestricted — shows trends and includes a food database, recipes and educational content. Data is encrypted. Core features are free with no card required; there is an API for developers. It works on iOS and Android.', 'Облік їжі за фото та голосом
Персональні плани під різні дієти
Тенденції та аналітика харчування
Безкоштовні основні функції', 'Food logging from photos and voice
Personal plans for different diets
Nutrition trends and analytics
Free core features', 'Люди, які хочуть стежити за харчуванням без ручного введення даних.', 'People who want to track their diet without manual data entry.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
